"use strict";

/* NK-Pro V99.4.71 – professionelles read-only Analysezentrum. */
const analyticsUiState={
  perspective:"nk",level:"dashboard",fromPeriodId:"",toPeriodId:"",comparison:"previous",referencePeriodId:"",
  detailSection:{nk:"costs",finance:"economics",tax:"transition"},
  filters:{
    nk:{costId:"all",costArea:"all",tenantId:"all",unitId:"all",usage:"all",allocationKey:"all",status:"all",dataQuality:"all",onlyOpenChecks:false,onlyAnomalies:false,displayMode:"total"},
    finance:{unitId:"all",tenantId:"all",paymentStatus:"all",costCategory:"all",objectCostType:"all",dataQuality:"all"},
    tax:{costId:"all",usage:"all",unitId:"all",classificationStatus:"all",taxYear:"all",dataQuality:"all"}
  },
  table:{query:"",sort:"0",direction:"asc",group:"none",hiddenColumns:{nk:[],finance:[],tax:[]}},detail:null
};
function analyticsText(v){return String(v===undefined||v===null?"":v).trim();}
function analyticsFinite(v){return v!==null&&v!==undefined&&v!==""&&Number.isFinite(Number(v));}
function analyticsNum(v){return analyticsFinite(v)?Number(v):0;}
function analyticsRound(v,d=2){if(!analyticsFinite(v))return null;const f=10**d;return Math.round((Number(v)+Number.EPSILON)*f)/f;}
function analyticsMoney(v){return analyticsFinite(v)?Number(v).toLocaleString("de-DE",{style:"currency",currency:"EUR",minimumFractionDigits:2,maximumFractionDigits:2}):"–";}
function analyticsMoneySigned(v){if(!analyticsFinite(v))return "–";return (Number(v)>0?"+":"")+analyticsMoney(v);}
function analyticsNumber(v,d=1){return analyticsFinite(v)?Number(v).toLocaleString("de-DE",{minimumFractionDigits:d,maximumFractionDigits:d}):"–";}
function analyticsPercent(v){return analyticsFinite(v)?((Number(v)>0?"+":"")+Number(v).toLocaleString("de-DE",{minimumFractionDigits:1,maximumFractionDigits:1})+" %"):"–";}
function analyticsEsc(v){return typeof escapeHtml==="function"?escapeHtml(v):analyticsText(v).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
function analyticsArgs(v){return analyticsEsc(JSON.stringify([v]));}
function analyticsSourceState(){return typeof canonicalAnalysisState==="function"?canonicalAnalysisState():state;}
function analyticsCurrentRaw(){return NK_PRO_MODULES.analyticsEngine.build(analyticsSourceState());}
function analyticsAvailablePeriods(){return analyticsCurrentRaw().periods||[];}
function analyticsFilter(){return analyticsUiState.filters[analyticsUiState.perspective]||analyticsUiState.filters.nk;}
function analyticsEnsureRange(){const p=analyticsAvailablePeriods();if(!p.length)return;if(!p.some(x=>x.periodId===analyticsUiState.fromPeriodId))analyticsUiState.fromPeriodId=p[0].periodId;if(!p.some(x=>x.periodId===analyticsUiState.toPeriodId))analyticsUiState.toPeriodId=p.at(-1).periodId;if(!p.some(x=>x.periodId===analyticsUiState.referencePeriodId))analyticsUiState.referencePeriodId=p[0].periodId;}
function analyticsSelectedPeriodIds(){analyticsEnsureRange();const p=analyticsAvailablePeriods(),a=Math.max(0,p.findIndex(x=>x.periodId===analyticsUiState.fromPeriodId)),b=Math.max(0,p.findIndex(x=>x.periodId===analyticsUiState.toPeriodId)),from=Math.min(a,b),to=Math.max(a,b);return p.slice(from,to+1).map(x=>x.periodId);}
function analyticsView(){const raw=NK_PRO_MODULES.analyticsEngine.build(analyticsSourceState(),{periodIds:analyticsSelectedPeriodIds()}),f=analyticsFilter();let models=(raw.models||[]).slice();if(f.dataQuality&&f.dataQuality!=="all")models=models.filter(m=>m.period&&m.period.quality&&m.period.quality.comparability===f.dataQuality);if(f.onlyOpenChecks)models=models.filter(m=>analyticsNum(m.quality&&m.quality.summary&&m.quality.summary.open)>0);const ids=new Set(models.map(m=>m.period.periodId));return Object.assign({},raw,{models,comparisons:(raw.comparisons||[]).filter(c=>ids.has(c.from.periodId)&&ids.has(c.to.periodId)),insights:(raw.insights||raw.anomalies||[]).filter(a=>!a.periodId||ids.has(a.periodId))});}
function analyticsLatest(view){return (view.models||[]).at(-1)||null;}
function analyticsModelByPeriod(view,id){return (view.models||[]).find(m=>m.period.periodId===id)||null;}
function analyticsPeriodOptions(periods,selected){return periods.map(p=>'<option value="'+analyticsEsc(p.periodId)+'"'+(p.periodId===selected?' selected':'')+'>'+analyticsEsc(p.label)+(p.quality&&p.quality.legacy?' · historisch':'')+'</option>').join('');}
function analyticsPeriodRangeLabel(){const all=analyticsAvailablePeriods(),ids=analyticsSelectedPeriodIds(),r=all.filter(p=>ids.includes(p.periodId));return !r.length?'Keine Periode':r.length===1?r[0].label:r[0].label+' – '+r.at(-1).label;}
function analyticsPerspectiveLabel(){return analyticsUiState.perspective==='finance'?'Finanzen':analyticsUiState.perspective==='tax'?'Steuerliche Auswertung':'Nebenkosten & Abrechnung';}
function analyticsSelect(value,options,action,label){return '<label class="analytics-filter-field"><span>'+analyticsEsc(label)+'</span><select data-ui-change="'+analyticsEsc(action)+'" data-ui-args="[&quot;$value&quot;]">'+options.map(o=>'<option value="'+analyticsEsc(o.value)+'"'+(String(o.value)===String(value)?' selected':'')+'>'+analyticsEsc(o.label)+'</option>').join('')+'</select></label>';}
function analyticsQualityClass(s){return s==='vergleichbar'?'success':s==='eingeschränkt vergleichbar'?'warning':'danger';}
function analyticsQualityBadge(modelOrStatus,reason=""){const s=typeof modelOrStatus==='string'?modelOrStatus:analyticsText(modelOrStatus&&modelOrStatus.period&&modelOrStatus.period.quality&&modelOrStatus.period.quality.comparability)||'nicht vergleichbar';return '<span class="analytics-quality-badge is-'+analyticsQualityClass(s)+'"'+(reason?' title="'+analyticsEsc(reason)+'"':'')+'>'+analyticsEsc(s)+'</span>';}
function analyticsEmpty(title,body){return '<div class="nk-ui-state nk-ui-state--empty analytics-empty"><strong>'+analyticsEsc(title)+'</strong><span>'+analyticsEsc(body)+'</span></div>';}

function analyticsComparison(view){const models=view.models||[];if(models.length<2||analyticsUiState.comparison==='none')return null;let a=null,b=models.at(-1);if(analyticsUiState.comparison==='reference')a=analyticsModelByPeriod(view,analyticsUiState.referencePeriodId);else if(analyticsUiState.comparison==='first')a=models[0];else if(analyticsUiState.comparison==='previous-year'){const y=Number(b.period.yearLabel);a=models.find(m=>m!==b&&Number(m.period.yearLabel)===y-1)||models.at(-2);}else a=models.at(-2);if(!a||!b||a.period.periodId===b.period.periodId)return null;return NK_PRO_MODULES.analyticsEngine.comparison(a,b);}
function analyticsMetricSet(view,p){const latest=analyticsLatest(view);if(!latest)return[];const raw=latest.metrics||{},cmp=analyticsComparison(view),m=cmp&&cmp.metrics?Object.assign({},raw,cmp.metrics):raw;return p==='finance'?[m.rentReceived,m.operatingCosts,m.operatingResult,m.cashflow]:p==='tax'?[m.taxRent,m.taxPrepayments,m.taxClassified,m.taxUnclassified]:[m.totalCosts,m.participantShare,m.prepayments,m.settlementBalance];}
function analyticsMetricValue(metric){if(!metric||metric.value===null)return '–';if(metric.unit==='EUR')return analyticsMoney(metric.value);if(metric.unit==='m³')return analyticsNumber(metric.value,2)+' m³';if(metric.unit==='EUR/m³')return analyticsNumber(metric.value,2)+' €/m³';if(metric.unit==='%')return analyticsNumber(metric.value,1)+' %';return analyticsNumber(metric.value,2)+' '+analyticsEsc(metric.unit||'');}
function analyticsMetricComparison(metric){if(!metric)return {html:'Keine Vergleichsdaten',tone:'neutral'};const c=metric.comparability||{},s=analyticsText(c.status);if(metric.value===null)return {html:analyticsEsc(metric.dataGap||'Wert ist aus den vorhandenen Daten nicht berechenbar.'),tone:'warning'};if(s==='nicht vergleichbar')return {html:'Vergleich noch nicht belastbar'+(c.reason?' · '+analyticsEsc(c.reason):''),tone:'warning'};if(metric.absoluteChange===null)return {html:s==='nicht bewertet'?'Kein Vergleich gewählt':analyticsEsc(c.reason||'Keine Veränderungsangabe verfügbar.'),tone:'neutral'};const delta=metric.unit==='EUR'?analyticsMoneySigned(metric.absoluteChange):metric.unit==='m³'?((metric.absoluteChange>0?'+':'')+analyticsNumber(metric.absoluteChange,2)+' m³'):((metric.absoluteChange>0?'+':'')+analyticsNumber(metric.absoluteChange,2)+' '+analyticsEsc(metric.unit||''));return {html:delta+(metric.percentChange!==null?' · '+analyticsPercent(metric.percentChange):'')+(s==='eingeschränkt vergleichbar'?' · eingeschränkt vergleichbar':''),tone:s==='eingeschränkt vergleichbar'?'warning':'neutral'};}
function analyticsHeroKpi(metric){const cmp=analyticsMetricComparison(metric),payload={type:'metric',key:metric&&metric.id,periodId:metric&&metric.period&&metric.period.periodId,target:metric&&metric.drilldownTargets&&metric.drilldownTargets[0]};return '<article class="analytics-center-kpi analytics-center-kpi--primary analytics-center-kpi--'+(metric&&metric.value===null?'warning':cmp.tone)+'" role="button" tabindex="0" data-ui-action="analytics.openDrill" data-ui-keydown="analytics.openDrill" data-ui-key="Enter" data-ui-args=\''+analyticsArgs(payload)+'\'><small>'+analyticsEsc(metric?metric.label:'Kennzahl')+'</small><strong>'+analyticsMetricValue(metric)+'</strong><span>'+cmp.html+'</span></article>';}
function analyticsKpiRow(view){return '<section class="analytics-kpi-layout"><div class="analytics-kpis-primary">'+analyticsMetricSet(view,analyticsUiState.perspective).map(analyticsHeroKpi).join('')+'</div></section>';}

function analyticsSvgLine(models,valueFn,formatFn=analyticsMoney){if(!models.length)return analyticsEmpty('Keine Zeitreihe','Keine Perioden vorhanden.');const values=models.map(m=>{const v=valueFn(m);return analyticsFinite(v)?Number(v):null;}),nums=values.filter(v=>v!==null);if(!nums.length)return analyticsEmpty('Keine berechenbaren Werte','Die Kennzahl ist für diese Auswahl nicht verfügbar.');const w=760,h=250,p={l:92,r:20,t:22,b:44},min=Math.min(0,...nums),max=Math.max(...nums,1),span=Math.max(1,max-min),x=i=>p.l+(models.length===1?(w-p.l-p.r)/2:i*(w-p.l-p.r)/(models.length-1)),y=v=>p.t+(max-v)*(h-p.t-p.b)/span,pts=values.map((v,i)=>v===null?null:[x(i),y(v)]),segments=[];let cur=[];pts.forEach(pt=>{if(pt)cur.push(pt);else if(cur.length){segments.push(cur);cur=[];}});if(cur.length)segments.push(cur);const grid=[0,.25,.5,.75,1].map(t=>{const v=min+(max-min)*t,Y=y(v);return '<line x1="'+p.l+'" y1="'+Y+'" x2="'+(w-p.r)+'" y2="'+Y+'" class="analytics-grid"/><text x="'+(p.l-8)+'" y="'+(Y+4)+'" text-anchor="end">'+analyticsEsc(formatFn(v))+'</text>';}).join('');const line=segments.map(s=>'<polyline class="analytics-line series-main" points="'+s.map(pt=>pt.join(',')).join(' ')+'"/>').join(''),dots=pts.map((pt,i)=>pt?'<g class="analytics-chart-point" tabindex="0" role="button" data-ui-action="analytics.openDrill" data-ui-keydown="analytics.openDrill" data-ui-key="Enter" data-ui-args=\''+analyticsArgs({type:'period',periodId:models[i].period.periodId,key:models[i].period.periodId})+'\'><circle cx="'+pt[0]+'" cy="'+pt[1]+'" r="5"/><title>'+analyticsEsc(models[i].period.label+': '+formatFn(values[i]))+'</title></g>':'').join(''),labels=models.map((m,i)=>'<text class="analytics-x-label" x="'+x(i)+'" y="'+(h-12)+'" text-anchor="middle">'+analyticsEsc(m.period.label)+'</text>').join('');return '<svg class="analytics-svg" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Zeitreihe">'+grid+line+dots+labels+'</svg>';}
function analyticsHorizontalBars(rows,valueFn,labelFn,formatFn=analyticsMoney,drillType='cost'){const values=rows.map(valueFn).filter(analyticsFinite).map(Number),max=Math.max(1,...values.map(Math.abs));return '<div class="analytics-horizontal-bars">'+rows.map(r=>{const v=valueFn(r),pct=analyticsFinite(v)?Math.min(100,Math.abs(Number(v))/max*100):0,key=r.costId||r.tenantId||r.unitId||'';return '<button type="button" class="analytics-horizontal-row" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:drillType,key,periodId:r.periodId})+'\'><span>'+analyticsEsc(labelFn(r))+'</span><i><b style="width:'+pct+'%"></b></i><strong>'+analyticsEsc(formatFn(v))+'</strong></button>';}).join('')+'</div>';}
function analyticsChartCard(title,subtitle,chart,extra=''){return '<section class="nk-ui-card analytics-chart-card '+extra+'"><header><div><h2>'+analyticsEsc(title)+'</h2><p>'+analyticsEsc(subtitle||'')+'</p></div></header><div class="analytics-chart-frame">'+chart+'</div></section>';}

function analyticsActiveFilterItems(){const f=analyticsFilter(),items=[];Object.entries(f).forEach(([k,v])=>{if(v===false||v==='all'||v==='total'||v===null||v===undefined)return;const labels={costId:'Kostenart',costArea:'Kostenbereich',tenantId:'Teilnehmer',unitId:'Wohnung',usage:'Nutzungsart',allocationKey:'Umlageschlüssel',status:'Status',dataQuality:'Datenvollständigkeit',onlyOpenChecks:'Offene Prüfungen',onlyAnomalies:'Auffälligkeiten',paymentStatus:'Zahlungsstatus',costCategory:'Kostenkategorie',objectCostType:'Objektkostenart',classificationStatus:'Klassifikation',taxYear:'Steuerjahr'};items.push({key:k,label:labels[k]||k,value:v===true?'aktiv':v});});return items;}
function analyticsFilterChips(){const items=analyticsActiveFilterItems();if(!items.length)return '';return '<div class="analytics-filter-chips">'+items.map(i=>'<button type="button" data-ui-action="analytics.resetFilter" data-ui-args=\''+analyticsArgs(i.key)+'\'>'+analyticsEsc(i.label)+': '+analyticsEsc(i.value)+' <b>×</b></button>').join('')+'</div>';}
function analyticsFilterToolbar(view){const p=analyticsAvailablePeriods(),all=analyticsCurrentRaw().models||[],f=analyticsFilter(),costs=new Map(),tenants=new Map(),units=new Map(),areas=new Set(),keys=new Set();all.forEach(m=>{m.costs.forEach(c=>{costs.set(c.costId,c.costName);if(c.area)areas.add(c.area);if(c.allocationKey)keys.add(c.allocationKey);});m.tenants.forEach(t=>{tenants.set(t.tenantId,t.name);units.set(t.unitId,t.unitName||t.unitId);});});const cmp=[{value:'previous',label:'Vorperiode'},{value:'previous-year',label:'Vorjahr'},{value:'first',label:'Erste Periode'},{value:'reference',label:'Freie Referenz'},{value:'none',label:'Kein Vergleich'}],active=analyticsActiveFilterItems().length;let body='';if(analyticsUiState.perspective==='nk')body=analyticsSelect(f.costId,[{value:'all',label:'Alle Kostenarten'},...Array.from(costs).map(([value,label])=>({value,label}))],'analytics.setCost','Kostenart')+analyticsSelect(f.costArea,[{value:'all',label:'Alle Kostenbereiche'},...Array.from(areas).sort().map(value=>({value,label:value}))],'analytics.setCostArea','Kostenbereich')+analyticsSelect(f.tenantId,[{value:'all',label:'Alle Teilnehmer'},...Array.from(tenants).map(([value,label])=>({value,label}))],'analytics.setTenant','Teilnehmer')+analyticsSelect(f.unitId,[{value:'all',label:'Alle Wohnungen'},...Array.from(units).map(([value,label])=>({value,label}))],'analytics.setUnit','Wohnung')+analyticsSelect(f.usage,[{value:'all',label:'Alle Nutzungsarten'},{value:'rented',label:'Vermietet'},{value:'private',label:'Privat / Eigen'}],'analytics.setUsage','Nutzungsart')+analyticsSelect(f.allocationKey,[{value:'all',label:'Alle Umlageschlüssel'},...Array.from(keys).sort().map(value=>({value,label:value}))],'analytics.setAllocationKey','Umlageschlüssel')+analyticsSelect(f.dataQuality,[{value:'all',label:'Alle Datenlagen'},{value:'vergleichbar',label:'Vergleichbar'},{value:'eingeschränkt vergleichbar',label:'Eingeschränkt vergleichbar'},{value:'nicht vergleichbar',label:'Nicht vergleichbar'}],'analytics.setDataQuality','Datenvollständigkeit')+'<label class="analytics-filter-check"><input type="checkbox" data-ui-change="analytics.toggleOpenChecks" data-ui-args="[&quot;$checked&quot;]"'+(f.onlyOpenChecks?' checked':'')+'><span>Nur offene Prüfungen</span></label>';
else if(analyticsUiState.perspective==='finance')body=analyticsSelect(f.unitId,[{value:'all',label:'Alle Wohnungen'},...Array.from(units).map(([value,label])=>({value,label}))],'analytics.setUnit','Wohnung')+analyticsSelect(f.tenantId,[{value:'all',label:'Alle Teilnehmer'},...Array.from(tenants).map(([value,label])=>({value,label}))],'analytics.setTenant','Teilnehmer')+analyticsSelect(f.paymentStatus,[{value:'all',label:'Alle Zahlungsstatus'},{value:'dated',label:'Datierte Zahlungen'},{value:'missing',label:'Zahlungsdaten fehlen'}],'analytics.setFinancePaymentStatus','Zahlungsstatus')+analyticsSelect(f.costCategory,[{value:'all',label:'Alle Kostenkategorien'},...Array.from(areas).sort().map(value=>({value,label:value}))],'analytics.setFinanceCostCategory','Kostenkategorie')+analyticsSelect(f.dataQuality,[{value:'all',label:'Alle Datenlagen'},{value:'vergleichbar',label:'Vergleichbar'},{value:'eingeschränkt vergleichbar',label:'Eingeschränkt vergleichbar'},{value:'nicht vergleichbar',label:'Nicht vergleichbar'}],'analytics.setDataQuality','Datenvollständigkeit');
else body=analyticsSelect(f.costId,[{value:'all',label:'Alle Kostenarten'},...Array.from(costs).map(([value,label])=>({value,label}))],'analytics.setCost','Kostenart')+analyticsSelect(f.usage,[{value:'all',label:'Alle Nutzungsarten'},{value:'rented',label:'Vermietet'},{value:'private',label:'Privat / Eigen'}],'analytics.setUsage','Nutzungsart')+analyticsSelect(f.unitId,[{value:'all',label:'Alle Wohnungen'},...Array.from(units).map(([value,label])=>({value,label}))],'analytics.setUnit','Wohnung')+analyticsSelect(f.classificationStatus,[{value:'all',label:'Alle Klassifikationen'},{value:'open',label:'Steuerliche Zuordnung offen'}],'analytics.setTaxClassificationStatus','Klassifikationsstatus')+analyticsSelect(f.taxYear,[{value:'all',label:'Alle Steuerjahre'},{value:'open',label:'Steuerjahr offen'}],'analytics.setTaxYear','Steuerjahr')+analyticsSelect(f.dataQuality,[{value:'all',label:'Alle Datenlagen'},{value:'vergleichbar',label:'Vergleichbar'},{value:'eingeschränkt vergleichbar',label:'Eingeschränkt vergleichbar'},{value:'nicht vergleichbar',label:'Nicht vergleichbar'}],'analytics.setDataQuality','Datenvollständigkeit');
return '<section class="analytics-command-shell"><div class="analytics-command-bar"><div class="analytics-period-command"><span>ZEITRAUM</span><div><select aria-label="Zeitraum von" data-ui-change="analytics.setFromPeriod" data-ui-args="[&quot;$value&quot;]">'+analyticsPeriodOptions(p,analyticsUiState.fromPeriodId)+'</select><i>–</i><select aria-label="Zeitraum bis" data-ui-change="analytics.setToPeriod" data-ui-args="[&quot;$value&quot;]">'+analyticsPeriodOptions(p,analyticsUiState.toPeriodId)+'</select></div></div><label class="analytics-command-select"><span>VERGLEICH</span><select data-ui-change="analytics.setComparison" data-ui-args="[&quot;$value&quot;]">'+cmp.map(o=>'<option value="'+o.value+'"'+(o.value===analyticsUiState.comparison?' selected':'')+'>'+o.label+'</option>').join('')+'</select></label><details class="analytics-filter-disclosure"><summary>Filter '+active+'</summary><div class="analytics-filter-panel">'+(analyticsUiState.comparison==='reference'?'<label><span>Referenz</span><select data-ui-change="analytics.setReferencePeriod" data-ui-args="[&quot;$value&quot;]">'+analyticsPeriodOptions(p,analyticsUiState.referencePeriodId)+'</select></label>':'')+'<div class="analytics-filter-grid">'+body+'</div><p>Perspektivspezifische Filter wirken auf die jeweilige Detail-/Tabellenanalyse; die vier Objekt-Hauptkennzahlen bleiben bewusst ungefilterte Objektwerte.</p></div></details>'+analyticsExportBar()+'</div>'+analyticsFilterChips()+'</section>';}
function analyticsPerspectiveTabs(){return '<div class="analytics-perspective-tabs" role="tablist" aria-label="Analyseperspektive"><button role="tab" aria-selected="'+(analyticsUiState.perspective==='nk')+'" data-ui-action="analytics.setPerspective" data-ui-args=\'["nk"]\'>Nebenkosten &amp; Abrechnung</button><button role="tab" aria-selected="'+(analyticsUiState.perspective==='finance')+'" data-ui-action="analytics.setPerspective" data-ui-args=\'["finance"]\'>Finanzen</button><button role="tab" aria-selected="'+(analyticsUiState.perspective==='tax')+'" data-ui-action="analytics.setPerspective" data-ui-args=\'["tax"]\'>Steuerliche Auswertung</button></div>';}
function analyticsLevelTabs(){return '<div class="analytics-view-toolbar"><div><strong>'+analyticsEsc(analyticsPerspectiveLabel())+'</strong><span>'+analyticsEsc(analyticsPeriodRangeLabel())+'</span></div><div class="analytics-level-tabs"><button aria-selected="'+(analyticsUiState.level==='dashboard')+'" data-ui-action="analytics.setLevel" data-ui-args=\'["dashboard"]\'>Übersicht</button><button aria-selected="'+(analyticsUiState.level==='detail')+'" data-ui-action="analytics.setLevel" data-ui-args=\'["detail"]\'>Details</button><button aria-selected="'+(analyticsUiState.level==='table')+'" data-ui-action="analytics.setLevel" data-ui-args=\'["table"]\'>Tabelle</button></div></div>';}
function analyticsExportBar(){return '<details class="analytics-export-menu"><summary>Export</summary><div><button data-ui-action="analytics.exportCsv" type="button">CSV</button><button data-ui-action="analytics.exportExcel" type="button">Excel</button><button data-ui-action="analytics.print" type="button">PDF / Druck</button></div></details>';}
function analyticsQuestionBar(){const p=analyticsUiState.perspective,qs=p==='finance'?[['owner-costs','Welche Kosten trägt der Eigentümer?'],['economics','Wie wirtschaftlich läuft das Objekt?']]:p==='tax'?[['private-tax','Wie entsteht mein Privatanteil?'],['transition','Welche Beträge sind noch ungeklärt?']]:[['cost-change','Was wurde teurer?'],['water','Warum sind Wasserkosten gestiegen?'],['balances','Wer hat hohe Nachzahlungen?'],['units-water','Welche Wohnungen verbrauchen am meisten?']];return '<div class="analytics-question-bar"><span>Analysefrage</span>'+qs.map(q=>'<button type="button" data-ui-action="analytics.askQuestion" data-ui-args=\''+analyticsArgs(q[0])+'\'>'+analyticsEsc(q[1])+'</button>').join('')+'</div>';}

function analyticsChangeExplanation(view){const cmp=analyticsComparison(view);if(!cmp)return '<section class="nk-ui-card analytics-change-card"><header><h2>Was hat sich verändert?</h2></header><p>Für die gewählte Auswahl ist kein belastbarer Vergleich vorhanden.</p></section>';const rows=[...(cmp.largestIncreases||[]),...(cmp.largestDecreases||[])].sort((a,b)=>Math.abs(b.delta||0)-Math.abs(a.delta||0)).slice(0,3);if(!rows.length&&cmp.newCosts&&cmp.newCosts.length)rows.push(...cmp.newCosts.slice(0,3));return '<section class="nk-ui-card analytics-change-card"><header><h2>Was hat sich verändert?</h2><p>'+analyticsEsc(cmp.from.label)+' → '+analyticsEsc(cmp.to.label)+'</p></header><ul class="analytics-change-list">'+rows.map(r=>'<li><button data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:'cost',key:r.costId,periodId:cmp.to.periodId})+'\'><span>'+analyticsEsc(r.costName)+'</span><b>'+(r.newCost?'Neu in dieser Periode':analyticsMoneySigned(r.delta))+'</b></button></li>').join('')+'</ul><button class="analytics-text-link" data-ui-action="analytics.setDetailSection" data-ui-args=\'["costs"]\'>Vollständige Ursachenanalyse →</button></section>';}
function analyticsInsightList(view,max=3,all=false){const rows=(view.insights||[]).slice().sort((a,b)=>({notice:0,info:1,data:2}[a.severity]??3)-({notice:0,info:1,data:2}[b.severity]??3));const shown=all?rows:rows.slice(0,max);if(!shown.length)return '<section class="analytics-insights"><header><h2>Auffälligkeiten</h2></header><p>Keine priorisierten Auffälligkeiten für die Auswahl.</p></section>';return '<section class="analytics-insights"><header><h2>'+(all?'Alle Hinweise':'Wichtige Auffälligkeiten')+'</h2></header><div>'+shown.map(r=>'<button class="analytics-insight-row" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:r.key==='water'?'water':r.key==='meters'?'period':'cost',key:r.key,periodId:r.periodId})+'\'><span><b>'+analyticsEsc(r.label)+'</b><small>'+analyticsEsc(r.detail)+'</small></span><em>'+analyticsEsc(r.category||'Analyse')+'</em></button>').join('')+'</div>'+(all?'':'<button class="analytics-text-link" data-ui-action="analytics.setDetailSection" data-ui-args=\'["insights"]\'>Alle Hinweise anzeigen →</button>')+'</section>';}
function analyticsDataQualityCompact(view){const models=view.models||[],good=models.filter(m=>m.period.quality.comparability==='vergleichbar').length,limited=models.filter(m=>m.period.quality.comparability==='eingeschränkt vergleichbar').length,status=good===models.length&&models.length?'vergleichbar':limited||good?'eingeschränkt vergleichbar':'nicht vergleichbar';return '<section class="analytics-quality-compact"><div><span>Datenlage</span>'+analyticsQualityBadge(status)+'</div><p>'+good+' von '+models.length+' Perioden direkt vergleichbar. Einschränkungen werden zusätzlich an betroffenen Kennzahlen ausgewiesen.</p></section>';}

function analyticsNkDashboard(view){const latest=analyticsLatest(view);if(!latest)return analyticsEmpty('Keine Analysedaten','Keine Periode verfügbar.');const trend=analyticsSvgLine(view.models,m=>m.metrics.totalCosts.value,analyticsMoney),costs=latest.costs.filter(c=>c.active&&c.total!==null).sort((a,b)=>b.total-a.total).slice(0,7);return analyticsKpiRow(view)+'<div class="analytics-hero-grid">'+analyticsChartCard('Kostenentwicklung','Wie entwickeln sich die Abrechnungskosten über die verfügbaren Perioden?',trend,'analytics-chart-card--hero')+analyticsChangeExplanation(view)+'</div>'+analyticsChartCard('Kostenstruktur','Welche Kostenarten prägen die aktuelle Periode?',analyticsHorizontalBars(costs,c=>c.total,c=>c.costName,analyticsMoney,'cost'))+analyticsInsightList(view,3,false)+analyticsDataQualityCompact(view);}
function analyticsSectionNav(items,active){return '<nav class="analytics-section-nav" aria-label="Detailbereiche">'+items.map(i=>'<button type="button" aria-current="'+(i[0]===active)+'" data-ui-action="analytics.setDetailSection" data-ui-args=\''+analyticsArgs(i[0])+'\'>'+analyticsEsc(i[1])+'</button>').join('')+'</nav>';}
function analyticsCostDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const f=analyticsUiState.filters.nk,costs=latest.costs.filter(c=>(f.costId==='all'||c.costId===f.costId)&&(f.costArea==='all'||c.area===f.costArea)&&(f.allocationKey==='all'||c.allocationKey===f.allocationKey)&&(c.active||c.total!==null));const cmp=analyticsComparison(view);return analyticsChartCard('Kostenartenranking','Aktuelle Kosten nach Höhe.',analyticsHorizontalBars(costs.slice().sort((a,b)=>(b.total||0)-(a.total||0)),c=>c.total,c=>c.costName,analyticsMoney,'cost'))+(cmp?'<section class="nk-ui-card analytics-table-card"><header><h2>Veränderungsursachen</h2><p>Keine Prozentwerte, wenn eine Vergleichsbasis fehlt oder nicht belastbar ist.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Kostenart</th><th>Vorher</th><th>Aktuell</th><th>Δ €</th><th>Δ %</th><th>Vergleichbarkeit</th></tr></thead><tbody>'+cmp.costs.filter(r=>costs.some(c=>c.costId===r.costId)).map(r=>'<tr><td>'+analyticsEsc(r.costName)+'</td><td class="money">'+analyticsMoney(r.before)+'</td><td class="money">'+analyticsMoney(r.after)+'</td><td class="money">'+analyticsMoneySigned(r.delta)+'</td><td>'+analyticsPercent(r.percent)+'</td><td>'+analyticsQualityBadge(r.comparability.status,r.comparability.reason)+'</td></tr>').join('')+'</tbody></table></div></section>':'');}
function analyticsWaterDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const w=latest.water,cmp=analyticsComparison(view),units=latest.units.filter(u=>u.waterAvailable).sort((a,b)=>b.water-a.water);let effect='<p>Preis-/Verbrauchszerlegung nicht berechenbar. Dafür werden belastbare Mengen- und Preiswerte in beiden Perioden benötigt.</p>';if(cmp&&cmp.waterEffects){const e=cmp.waterEffects;effect='<div class="analytics-effect-grid"><div><span>Kostenänderung</span><strong>'+analyticsMoneySigned(e.costDelta)+'</strong></div><div><span>Verbrauchseffekt</span><strong>'+analyticsMoneySigned(e.quantityEffect)+'</strong></div><div><span>Preiseffekt</span><strong>'+analyticsMoneySigned(e.priceEffect)+'</strong></div><div><span>Struktur/Rest</span><strong>'+analyticsMoneySigned(e.otherEffect)+'</strong></div></div><p>'+analyticsEsc(e.method)+'</p>';}
return '<section class="analytics-water-kpis"><div><span>Hausgesamtverbrauch / Unterzähler</span><strong>'+(w.available?analyticsNumber(w.total,2)+' m³':'–')+'</strong></div><div><span>Kaltwasser</span><strong>'+analyticsNumber(w.cold,2)+' m³</strong></div><div><span>Warmwasser</span><strong>'+analyticsNumber(w.warm,2)+' m³</strong></div><div><span>Preis je m³</span><strong>'+(latest.waterPrice===null?'–':analyticsNumber(latest.waterPrice,2)+' €')+'</strong></div><div><span>Hauszählerdifferenz</span><strong>'+(w.houseDifference===null?'–':analyticsNumber(w.houseDifference,2)+' m³')+'</strong></div><div><span>Liter je Person/Tag</span><strong>'+(w.litersPerPersonDay===null?'–':analyticsNumber(w.litersPerPersonDay,1)+' l')+'</strong></div></section>'+analyticsChartCard('Wasserverbrauch nach Wohnung','Differenzen sind Hinweise, nicht automatisch Fehler.',analyticsHorizontalBars(units,u=>u.water,u=>u.unitName,v=>analyticsNumber(v,2)+' m³','unit'))+'<section class="nk-ui-card analytics-effect-card"><header><h2>Preis-/Verbrauchseffekt</h2><p>Warum haben sich die Wasserkosten verändert?</p></header>'+effect+'</section>'+analyticsMeterPanel(latest);}
function analyticsMeterPanel(model){return '<section class="nk-ui-card analytics-meter-panel"><header><h2>Zähler & Messperioden</h2><p>'+analyticsEsc(model.meter.source||'')+'</p></header><div class="analytics-meter-kpis"><span><b>'+model.meter.meters+'</b>Zähler</span><span><b>'+model.meter.readings+'</b>Messwerte</span><span><b>'+model.meter.measurementPeriods+'</b>Messperioden</span><span><b>'+model.meter.replacements+'</b>Zählerwechsel</span></div>'+(model.meter.missingValues||model.meter.invalidPeriods?'<p class="analytics-warning-text">'+(model.meter.missingValues+model.meter.invalidPeriods)+' Mess-/Periodenhinweise prüfen.</p>':'<p>Keine problematischen Messwerte in der ausgewerteten Menge erkannt.</p>')+'</section>';}
function analyticsTenantDetail(view){const latest=analyticsLatest(view),f=analyticsUiState.filters.nk;if(!latest)return '';const rows=latest.tenants.filter(t=>(f.tenantId==='all'||t.tenantId===f.tenantId)&&(f.unitId==='all'||t.unitId===f.unitId)&&(f.usage==='all'||t.usage===f.usage)).sort((a,b)=>b.costShare-a.costShare);return '<section class="nk-ui-card analytics-table-card"><header><h2>Teilnehmeranalyse</h2><p>Privat-/Eigenanteile bleiben reguläre Teilnehmer und werden nur als Nutzungsart gekennzeichnet.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Teilnehmer</th><th>Wohnung</th><th>Nutzungsart</th><th>Kostenanteil</th><th>Vorauszahlungen</th><th>Saldo</th></tr></thead><tbody>'+rows.map(t=>'<tr><td><button class="analytics-cell-link" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:'tenant',key:t.tenantId,periodId:t.periodId})+'\'>'+analyticsEsc(t.name)+'</button></td><td>'+analyticsEsc(t.unitName)+'</td><td><span class="analytics-usage-badge">'+analyticsEsc(t.usageLabel)+'</span></td><td class="money">'+analyticsMoney(t.costShare)+'</td><td class="money">'+analyticsMoney(t.prepayments)+'</td><td class="money">'+analyticsMoneySigned(t.balance)+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsHousingDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const rows=latest.units.slice().sort((a,b)=>b.participantCost-a.participantCost);return '<section class="nk-ui-card analytics-table-card"><header><h2>Wohnungsanalyse</h2><p>Aktuelle Objektstammdaten haben Vorrang vor historischen 55-m²-Platzhaltern.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Wohnung</th><th>Wohnfläche</th><th>historische Fläche</th><th>Kosten</th><th>€/m²</th><th>Wasser</th><th>Leerstandstage</th></tr></thead><tbody>'+rows.map(u=>'<tr><td><button class="analytics-cell-link" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:'unit',key:u.unitId,periodId:u.periodId})+'\'>'+analyticsEsc(u.unitName)+'</button></td><td>'+analyticsNumber(u.area,1)+' m²</td><td>'+(u.historicalArea!==null&&u.historicalArea!==u.area?analyticsNumber(u.historicalArea,1)+' m² · historischer Wert':'–')+'</td><td class="money">'+analyticsMoney(u.participantCost)+'</td><td>'+analyticsNumber(u.costPerSqm,2)+' €</td><td>'+(u.waterAvailable?analyticsNumber(u.water,2)+' m³':'–')+'</td><td>'+(u.vacancyDays===null?'Daten fehlen':u.vacancyDays)+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsBalanceDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const rows=latest.tenants.slice().sort((a,b)=>b.balance-a.balance);return analyticsChartCard('Vorauszahlungen & Salden','Positive Werte sind Nachzahlungen, negative Werte Guthaben.',analyticsHorizontalBars(rows,t=>Math.abs(t.balance),t=>t.name,v=>analyticsMoney(v),'tenant'))+'<section class="nk-ui-card analytics-table-card"><div class="nk-ui-table-wrap"><table><thead><tr><th>Teilnehmer</th><th>Kostenanteil</th><th>Vorauszahlungen</th><th>Saldo</th></tr></thead><tbody>'+rows.map(t=>'<tr><td>'+analyticsEsc(t.name)+'</td><td class="money">'+analyticsMoney(t.costShare)+'</td><td class="money">'+analyticsMoney(t.prepayments)+'</td><td class="money '+(t.balance>0?'is-positive':'is-negative')+'">'+analyticsMoneySigned(t.balance)+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsVacancyDetail(view){const latest=analyticsLatest(view);if(!latest)return '';return '<section class="nk-ui-card analytics-table-card"><header><h2>Leerstand</h2><p>Leerstand bleibt fachlich vollständig von Privatnutzung getrennt.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Wohnung</th><th>Leerstandstage</th><th>Leerstandskosten</th><th>Status</th></tr></thead><tbody>'+latest.units.map(u=>'<tr><td>'+analyticsEsc(u.unitName)+'</td><td>'+(u.vacancyDays===null?'nicht berechenbar':u.vacancyDays)+'</td><td class="money">'+analyticsMoney(latest.costs.reduce((s,c)=>s+(c.vacancyShare||0),0)*(u.vacancyDays&&latest.totals.vacancyDays?u.vacancyDays/latest.totals.vacancyDays:0))+'</td><td>'+analyticsEsc(u.occupancyStatus)+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsUnallocatedDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const a=latest.costs.filter(c=>c.trueNonAllocable>.005),b=latest.costs.filter(c=>c.actualUnallocated>.005);const block=(title,rows,field)=>'<section class="nk-ui-card analytics-table-card"><header><h2>'+title+'</h2></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Kostenart</th><th>Betrag</th></tr></thead><tbody>'+rows.map(c=>'<tr><td>'+analyticsEsc(c.costName)+'</td><td class="money">'+analyticsMoney(c[field])+'</td></tr>').join('')+'</tbody></table></div></section>';return block('Echte nicht umlagefähige Kosten',a,'trueNonAllocable')+block('Grundsätzlich umlagefähig, tatsächlich nicht umgelegt',b,'actualUnallocated');}
function analyticsPeriodQualityDetails(view){return '<section class="nk-ui-card analytics-table-card"><header><h2>Datenqualität & Vergleichbarkeit</h2><p>Kennzahlenbezogene Bewertung statt Scheinscore.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Periode</th><th>Status</th><th>Abdeckung</th><th>Gründe</th></tr></thead><tbody>'+view.models.map(m=>'<tr><td>'+analyticsEsc(m.period.label)+'</td><td>'+analyticsQualityBadge(m)+'</td><td>'+analyticsEsc(m.period.quality.coverage)+'</td><td>'+analyticsEsc((m.period.quality.issues||[]).join(' · ')||'Keine periodenspezifische Einschränkung')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsNkDetail(view){const items=[['costs','Kosten'],['water','Verbrauch & Zähler'],['participants','Teilnehmer'],['units','Wohnungen'],['balances','Vorauszahlungen & Salden'],['vacancy','Leerstand'],['unallocated','Nicht umgelegte Kosten'],['insights','Auffälligkeiten'],['quality','Datenqualität']],active=analyticsUiState.detailSection.nk;let body=active==='water'?analyticsWaterDetail(view):active==='participants'?analyticsTenantDetail(view):active==='units'?analyticsHousingDetail(view):active==='balances'?analyticsBalanceDetail(view):active==='vacancy'?analyticsVacancyDetail(view):active==='unallocated'?analyticsUnallocatedDetail(view):active==='insights'?analyticsInsightList(view,99,true):active==='quality'?analyticsPeriodQualityDetails(view):analyticsCostDetail(view);return analyticsSectionNav(items,active)+body;}

function analyticsFinancialBridge(model){const f=model.financial,steps=[['Vereinnahmte Kaltmiete',f.rentReceived],['NK-Vorauszahlungen',f.nkPrepayments],['Sonstige echte Einnahmen',f.otherIncome],['Laufende Objektkosten',-f.operatingCosts],['Objektbetriebsergebnis',f.operatingResult]];return '<section class="nk-ui-card analytics-bridge-card"><header><h2>Vom Mieterlös zum Objektbetriebsergebnis</h2><p>Vor Finanzierung und Investitionen; nur vorhandene Werte.</p></header><div class="analytics-bridge-list">'+steps.map((s,i)=>'<div class="'+(i===steps.length-1?'is-result':'')+'"><span>'+analyticsEsc(s[0])+'</span><strong>'+analyticsMoneySigned(s[1])+'</strong></div>').join('')+'</div></section>';}
function analyticsOwnerCoverage(model){const c=model.financial.costCoverage;return '<section class="nk-ui-card analytics-bridge-card"><header><h2>Kostenweitergabe / Eigentümerbelastung</h2><p>Welche Objektbetriebskosten verbleiben wo – Privatanteil und Leerstand bleiben getrennt.</p></header><div class="analytics-bridge-list"><div><span>Objektbetriebskosten insgesamt</span><strong>'+analyticsMoney(c.total)+'</strong></div><div><span>Durch vermietete Teilnehmer getragen</span><strong>'+analyticsMoney(c.rentedCovered)+'</strong></div><div><span>Privatanteil</span><strong>'+analyticsMoney(c.privateShare)+'</strong></div><div><span>Leerstand</span><strong>'+analyticsMoney(c.vacancyShare)+'</strong></div><div><span>Umlagefähig, nicht umgelegt</span><strong>'+analyticsMoney(c.unallocatedAllocable)+'</strong></div><div><span>Echte nicht umlagefähige Kosten</span><strong>'+analyticsMoney(c.trueNonAllocable)+'</strong></div></div></section>';}
function analyticsFinanceDashboard(view){const latest=analyticsLatest(view);if(!latest)return analyticsEmpty('Keine Finanzdaten','Keine Periode verfügbar.');return analyticsKpiRow(view)+'<div class="analytics-hero-grid">'+analyticsChartCard('Objektbetriebsergebnis','Entwicklung vor Finanzierung und Investitionen.',analyticsSvgLine(view.models,m=>m.metrics.operatingResult.value,analyticsMoney),'analytics-chart-card--hero')+analyticsFinancialBridge(latest)+'</div>'+analyticsOwnerCoverage(latest)+analyticsInsightList(view,3,false)+analyticsDataQualityCompact(view);}
function analyticsFinanceDetail(view){const latest=analyticsLatest(view);if(!latest)return '';const items=[['economics','Wirtschaftlichkeit'],['owner-costs','Eigentümerbelastung'],['income','Einnahmen'],['expenses','Ausgaben'],['cashflow','Cashflow'],['quality','Datenqualität']],active=analyticsUiState.detailSection.finance;let body='';if(active==='owner-costs')body=analyticsOwnerCoverage(latest);else if(active==='cashflow')body=latest.financial.cashflowComplete?'<section class="nk-ui-card"><h2>Cashflow</h2><strong>'+analyticsMoney(latest.financial.cashflow)+'</strong></section>':'<section class="nk-ui-card analytics-gap-card"><strong>Cashflow derzeit nicht verfügbar</strong><span>'+analyticsEsc(latest.financial.cashflowReason)+'</span><button class="analytics-text-link" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:'metric',key:'finance.cashflow',periodId:latest.period.periodId,target:'payments'})+'\'>Benötigte Daten ansehen →</button></section>';else if(active==='income'){const f=analyticsUiState.filters.finance,rows=latest.tenants.filter(t=>t.usage==='rented'&&(f.tenantId==='all'||t.tenantId===f.tenantId)&&(f.unitId==='all'||t.unitId===f.unitId));body='<section class="nk-ui-card analytics-table-card"><header><h2>Einnahmen</h2></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Teilnehmer</th><th>Wohnung</th><th>Kaltmiete Soll</th><th>Kaltmiete Ist</th><th>NK-Vorauszahlungen</th></tr></thead><tbody>'+rows.map(t=>'<tr><td>'+analyticsEsc(t.name)+'</td><td>'+analyticsEsc(t.unitName)+'</td><td class="money">'+analyticsMoney(t.coldRentTarget)+'</td><td class="money">'+analyticsMoney(t.coldRentReceived)+'</td><td class="money">'+analyticsMoney(t.prepayments)+'</td></tr>').join('')+'</tbody></table></div></section>';}else if(active==='expenses')body=analyticsCostDetail(view);else if(active==='quality')body=analyticsPeriodQualityDetails(view);else body=analyticsFinancialBridge(latest)+analyticsOwnerCoverage(latest);return analyticsSectionNav(items,active)+body;}

function analyticsTaxNotice(){return '<aside class="nk-ui-notice nk-ui-notice--info analytics-tax-notice"><strong>Steuerliche Auswertung – keine Steuerberatung</strong><span>NK-Pro bereitet vorhandene Objektwerte nachvollziehbar auf. Ohne explizite fachliche Regel bleiben Steuerkategorie und Steuerjahr offen; es erfolgt keine automatische Steuerannahme.</span></aside>';}
function analyticsTaxTransitionTable(view){const latest=analyticsLatest(view);if(!latest)return '';const f=analyticsUiState.filters.tax,rows=latest.tax.filter(r=>(f.costId==='all'||r.costId===f.costId)&&(f.classificationStatus==='all'||(f.classificationStatus==='open'?r.taxValue===null:r.taxValue!==null)));return '<section class="nk-ui-card analytics-table-card"><header><h2>Steuerliche Überleitung</h2><p>Gesamtkosten → vermietet → privat → Leerstand → sonstige Zuordnung → Steuerkategorie → Steuerjahr.</p></header><div class="nk-ui-table-wrap"><table><thead><tr><th>Kostenart</th><th>Gesamt</th><th>Vermietet</th><th>Privat</th><th>Leerstand</th><th>Sonstige</th><th>Steuerliche Zuordnung</th><th>Steuerjahr</th><th>Status</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><button class="analytics-cell-link" data-ui-action="analytics.openDrill" data-ui-args=\''+analyticsArgs({type:'tax-cost',key:r.costId,periodId:r.periodId})+'\'>'+analyticsEsc(r.costName)+'</button></td><td class="money">'+analyticsMoney(r.total)+'</td><td class="money">'+analyticsMoney(r.rented)+'</td><td class="money">'+analyticsMoney(r.private)+'</td><td class="money">'+analyticsMoney(r.vacancy)+'</td><td class="money">'+analyticsMoney(r.other)+'</td><td>'+analyticsEsc(r.taxCategory||'Steuerliche Zuordnung offen')+'</td><td>'+analyticsEsc(r.taxYear||'offen')+'</td><td><span class="analytics-tax-unclassified">'+analyticsEsc(r.taxValue===null?'Steuerliche Zuordnung offen':r.taxStatus)+'</span></td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsPrivateTax(view){const latest=analyticsLatest(view);if(!latest)return '';const privateTenants=latest.tenants.filter(t=>t.usage==='private'),rows=latest.tax.filter(r=>analyticsFinite(r.private)&&Math.abs(Number(r.private))>.005);return '<section class="nk-ui-card analytics-table-card"><header><h2>Privatanteil</h2><p>Private Nutzung wird generisch über die Nutzungsart erkannt; sie bleibt in der Nebenkostenlogik regulärer Abrechnungsteilnehmer.</p></header><div class="analytics-private-participants">'+privateTenants.map(t=>'<div><strong>'+analyticsEsc(t.name)+'</strong><span>'+analyticsEsc(t.unitName||t.unitId)+' · '+analyticsEsc(t.usageLabel)+'</span><b>'+analyticsMoney(t.costShare)+'</b></div>').join('')+'</div><div class="nk-ui-table-wrap"><table><thead><tr><th>Kostenart</th><th>Privatanteil</th><th>Umlageschlüssel</th><th>Periode</th><th>Herkunft</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+analyticsEsc(r.costName)+'</td><td class="money">'+analyticsMoney(r.private)+'</td><td>'+analyticsEsc(r.allocationKey||'–')+'</td><td>'+analyticsEsc(r.periodLabel)+'</td><td>'+analyticsEsc(r.source||'–')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function analyticsTaxDashboard(view){const latest=analyticsLatest(view);if(!latest)return analyticsEmpty('Keine steuerlichen Auswertungsdaten','Keine Periode verfügbar.');const open='<section class="nk-ui-card analytics-tax-open-summary"><header><h2>Was ist steuerlich noch offen?</h2><p>Keine stille Klassifikation.</p></header><ul class="analytics-change-list"><li><span>Ungeklärte Kostenpositionen</span><b>'+latest.tax.filter(r=>r.taxValue===null).length+'</b></li><li><span>Steuerjahr ohne explizite Zuordnung</span><b>'+latest.tax.filter(r=>r.taxYear===null).length+'</b></li><li><span>Privat genutzte Teilnehmer</span><b>'+latest.tenants.filter(t=>t.usage==='private').length+'</b></li></ul></section>';return analyticsTaxNotice()+analyticsKpiRow(view)+analyticsTaxTransitionTable({models:[latest]})+open+analyticsInsightList(view,3,false)+analyticsDataQualityCompact(view);}
function analyticsTaxDetail(view){const items=[['transition','Steuerliche Überleitung'],['private-tax','Privatanteil'],['vacancy-tax','Leerstand'],['classification','Klassifikation'],['quality','Datenqualität']],active=analyticsUiState.detailSection.tax;let body=active==='private-tax'?analyticsPrivateTax(view):active==='vacancy-tax'?analyticsVacancyDetail(view):active==='quality'?analyticsPeriodQualityDetails(view):analyticsTaxTransitionTable(view);return analyticsTaxNotice()+analyticsSectionNav(items,active)+body;}

function analyticsTableFormat(value,format){if(value===null||value===undefined||value==='')return '–';if(format==='money')return analyticsMoney(value);if(format==='percent')return analyticsFinite(value)?analyticsNumber(value,1)+' %':'–';if(format==='number')return analyticsFinite(value)?analyticsNumber(value,2):analyticsEsc(value);return analyticsEsc(value);}
function analyticsTableExplorer(view){const perspective=analyticsUiState.perspective,models=view.models||[],q=analyticsUiState.table.query.toLowerCase();let header=[],formats=[],rows=[],groupOptions=[{value:'none',label:'Keine Gruppierung'}];if(perspective==='finance'){header=['Periode','Miete Soll','Miete Ist','Mietrealisierung','NK-Vorauszahlungen','Laufende Objektkosten','Objektbetriebsergebnis','Cashflow'];formats=['text','money','money','percent','money','money','money','money'];rows=models.map(m=>({cells:[m.period.label,m.financial.rentTarget,m.financial.rentReceived,m.financial.rentRealization,m.financial.nkPrepayments,m.financial.operatingCosts,m.financial.operatingResult,m.financial.cashflowComplete?m.financial.cashflow:null],groupPeriod:m.period.label,groupCategory:'Objektwirtschaftlichkeit',detail:'Cashflow: '+(m.financial.cashflowComplete?analyticsMoney(m.financial.cashflow):m.financial.cashflowReason)+' · Datenlage: '+m.period.quality.comparability}));groupOptions.push({value:'period',label:'Nach Periode'},{value:'category',label:'Nach Kategorie'});}else if(perspective==='tax'){header=['Periode','Kostenart','Gesamt','Vermietet','Privat','Leerstand','Sonstige','Steuerliche Zuordnung','Steuerjahr','Status'];formats=['text','text','money','money','money','money','money','text','text','text'];rows=models.flatMap(m=>m.tax.map(r=>{const c=m.costs.find(x=>x.costId===r.costId);return {cells:[m.period.label,r.costName,r.total,r.rented,r.private,r.vacancy,r.other,r.taxCategory||'Steuerliche Zuordnung offen',r.taxYear||'offen',r.taxValue===null?'Steuerliche Zuordnung offen':r.taxStatus],groupPeriod:m.period.label,groupCategory:(c&&c.area)||'Ohne Kategorie',detail:'Umlageschlüssel: '+(r.allocationKey||'–')+' · Quelle: '+(r.source||'–')};}));groupOptions.push({value:'period',label:'Nach Periode'},{value:'category',label:'Nach Kostenbereich'});}else{const ids=new Map();models.forEach(m=>m.costs.filter(c=>c.active||c.total!==null).forEach(c=>ids.set(c.costId,c.costName)));header=['Kostenart',...models.map(m=>m.period.label),'Durchschnitt','Δ €','Δ %'];formats=['text',...models.map(()=> 'money'),'money','money','percent'];rows=Array.from(ids.entries()).map(([id,name])=>{const values=models.map(m=>{const c=m.costs.find(x=>x.costId===id);return c&&c.total!==null?c.total:null;}),numeric=values.filter(analyticsFinite).map(Number),avg=numeric.length?numeric.reduce((a,b)=>a+b,0)/numeric.length:null,cmp=models.length>1?NK_PRO_MODULES.analyticsEngine.compareCosts(models.at(-2),models.at(-1)).find(x=>x.costId===id):null,sample=models.map(m=>m.costs.find(x=>x.costId===id)).find(Boolean),area=sample&&sample.area||'Ohne Kostenbereich';return {cells:[name,...values,avg,cmp?cmp.absoluteChange:null,cmp?cmp.percentChange:null],groupCategory:area,groupPeriod:'Mehrjahresmatrix',detail:'Kosten-ID: '+id+' · Bereich: '+area+' · Umlageschlüssel: '+(sample&&sample.allocationKey||'–')+' · Vergleich: '+(cmp&&cmp.comparability&&cmp.comparability.reason||'kein belastbarer Vergleich')};});groupOptions.push({value:'category',label:'Nach Kostenbereich'});}
rows=rows.filter(r=>!q||r.cells.some(v=>analyticsText(v).toLowerCase().includes(q))||analyticsText(r.detail).toLowerCase().includes(q));const sortIndex=Math.min(header.length-1,Math.max(0,Number(analyticsUiState.table.sort)||0)),dir=analyticsUiState.table.direction==='desc'?-1:1;rows.sort((a,b)=>{const av=a.cells[sortIndex],bv=b.cells[sortIndex];if(analyticsFinite(av)&&analyticsFinite(bv))return (Number(av)-Number(bv))*dir;return analyticsText(av).localeCompare(analyticsText(bv),'de')*dir;});const hidden=(analyticsUiState.table.hiddenColumns[perspective]||[]).filter(i=>i>0&&i<header.length),visible=header.map((_,i)=>i).filter(i=>!hidden.includes(i)),group=analyticsUiState.table.group,groupKey=r=>group==='period'?r.groupPeriod:group==='category'?r.groupCategory:'';let last=null,body='';rows.forEach(r=>{const g=groupKey(r);if(group!=='none'&&g!==last){body+='<tr class="analytics-table-group"><th colspan="'+visible.length+'" scope="rowgroup">'+analyticsEsc(g||'Ohne Gruppe')+'</th></tr>';last=g;}body+='<tr>'+visible.map(i=>'<td class="'+(['money','number','percent'].includes(formats[i])?'numeric':'')+'">'+analyticsTableFormat(r.cells[i],formats[i])+'</td>').join('')+'</tr><tr class="analytics-table-detail-row"><td colspan="'+visible.length+'"><details><summary>Detailzeile öffnen</summary><span>'+analyticsEsc(r.detail)+'</span></details></td></tr>';});if(!body)body='<tr><td colspan="'+Math.max(1,visible.length)+'">Keine passenden Tabellenzeilen.</td></tr>';const columnMenu='<details class="analytics-column-menu"><summary>Spalten</summary><div>'+header.map((h,i)=>'<label><input type="checkbox" '+(i===0?'disabled ':'')+(!hidden.includes(i)?'checked ':'')+'data-ui-change="analytics.toggleTableColumn" data-ui-args=\'[&quot;'+i+'&quot;,&quot;$checked&quot;]\'><span>'+analyticsEsc(h)+'</span></label>').join('')+'</div></details>';return '<section class="nk-ui-card analytics-table-card analytics-table-explorer"><header><h2>Tabellenansicht</h2><p>Präzise Werte aus derselben Analyseengine wie Dashboard, Tooltip und Export.</p></header><div class="analytics-table-tools"><label><span>Suche</span><input type="search" value="'+analyticsEsc(analyticsUiState.table.query)+'" placeholder="Suchen …" data-ui-input="analytics.setTableQuery" data-ui-args="[&quot;$value&quot;]"></label><label><span>Sortierung</span><select data-ui-change="analytics.setTableSort" data-ui-args="[&quot;$value&quot;]">'+header.map((h,i)=>'<option value="'+i+'"'+(String(sortIndex)===String(i)?' selected':'')+'>'+analyticsEsc(h)+'</option>').join('')+'</select></label><label><span>Gruppierung</span><select data-ui-change="analytics.setTableGroup" data-ui-args="[&quot;$value&quot;]">'+groupOptions.map(o=>'<option value="'+o.value+'"'+(o.value===group?' selected':'')+'>'+analyticsEsc(o.label)+'</option>').join('')+'</select></label><button type="button" data-ui-action="analytics.toggleTableDirection">'+(analyticsUiState.table.direction==='asc'?'Aufsteigend ↑':'Absteigend ↓')+'</button>'+columnMenu+analyticsExportBar()+'</div><div class="nk-ui-table-wrap"><table><thead><tr>'+visible.map(i=>'<th scope="col">'+analyticsEsc(header[i])+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div></section>';}

function analyticsDrillPanel(view){const d=analyticsUiState.detail;if(!d)return '';const model=analyticsModelByPeriod(view,d.periodId)||analyticsLatest(view);if(!model)return '';const table=rows=>'<table>'+rows.map(r=>'<tr><th>'+analyticsEsc(r[0])+'</th><td>'+r[1]+'</td></tr>').join('')+'</table>';let title='Details',body='';if(d.type==='cost'||d.type==='tax-cost'){const c=model.costs.find(r=>r.costId===d.key),t=model.tax.find(r=>r.costId===d.key);if(c){title=c.costName;body=table([['Periode',analyticsEsc(model.period.label)],['Gesamtkosten',analyticsMoney(c.total)],['Vermietet',analyticsMoney(c.rentedShare)],['Privat',analyticsMoney(c.privateShare)],['Leerstand',analyticsMoney(c.vacancyShare)],['Nicht umlagefähig',analyticsMoney(c.trueNonAllocable)],['Nicht umgelegt',analyticsMoney(c.actualUnallocated)],['Umlageschlüssel',analyticsEsc(c.allocationKey||'–')],['Berechnungsstatus',analyticsEsc(c.calculationStatus||'–')],['Quelle',analyticsEsc(c.source||'–')],['Steuerstatus',analyticsEsc(t&&t.taxStatus||'nicht betrachtet')]]);}}else if(d.type==='tenant'){const t=model.tenants.find(r=>r.tenantId===d.key);if(t){title=t.name;body=table([['Wohnung',analyticsEsc(t.unitName||t.unitId)],['Nutzungsart',analyticsEsc(t.usageLabel)],['Kostenanteil',analyticsMoney(t.costShare)],['Vorauszahlungen',analyticsMoney(t.prepayments)],['Saldo',analyticsMoneySigned(t.balance)],['Fläche',analyticsNumber(t.area,1)+' m²'],['Aktiver Zeitraum',analyticsEsc((t.start||'–')+' – '+(t.end||'offen'))]]);}}else if(d.type==='unit'){const u=model.units.find(r=>r.unitId===d.key);if(u){title=u.unitName;body=table([['Wohnfläche',analyticsNumber(u.area,1)+' m²'],['Flächenquelle',analyticsEsc(u.areaSource||'–')],['Historische Fläche',u.historicalArea===null?'–':analyticsNumber(u.historicalArea,1)+' m²'],['Kosten',analyticsMoney(u.participantCost)],['Kosten je m²',analyticsNumber(u.costPerSqm,2)+' €'],['Wasser',u.waterAvailable?analyticsNumber(u.water,2)+' m³':'–'],['Leerstandstage',u.vacancyDays===null?'Daten fehlen':analyticsEsc(u.vacancyDays)]]);}}else if(d.type==='water'){title='Wasser · '+model.period.label;body=table([['Gesamtverbrauch',analyticsNumber(model.water.total,2)+' m³'],['Kaltwasser',analyticsNumber(model.water.cold,2)+' m³'],['Warmwasser',analyticsNumber(model.water.warm,2)+' m³'],['Preis/m³',analyticsNumber(model.waterPrice,2)+' €'],['Hauszähler',analyticsNumber(model.water.houseTotal,2)+' m³'],['Haus-/Unterzählerdifferenz',analyticsNumber(model.water.houseDifference,2)+' m³ · '+analyticsPercent(model.water.houseDifferencePercent)],['Datenabdeckung',analyticsEsc(model.water.coverage)],['Quelle',analyticsEsc(model.water.source||'–')]]);}else if(d.type==='metric'){const metric=Object.values(model.metrics||{}).find(m=>m.id===d.key);if(metric){title=metric.label;body=table([['Periode',analyticsEsc(model.period.label)],['Wert',analyticsMetricValue(metric)],['Status',analyticsEsc(metric.status)],['Datenqualität',analyticsEsc(metric.dataQuality)],['Datenabdeckung',analyticsEsc(metric.dataCoverage)],['Berechnungsweg',analyticsEsc(metric.calculation)],['Quellen',analyticsEsc((metric.sources||[]).join(' · ')||'–')],['Datenlücke',analyticsEsc(metric.dataGap||'–')]]);}}else{title='Periode '+model.period.label;body=table([['Quelle',analyticsEsc(model.period.source)],['Zeitraum',analyticsEsc((model.period.start||'–')+' – '+(model.period.end||'–'))],['Vergleichbarkeit',analyticsQualityBadge(model)],['Periodenstatus',analyticsEsc(model.period.quality.completion.label)],['Hinweise',analyticsEsc((model.period.quality.issues||[]).join(' · ')||'Keine periodenspezifischen Hinweise')]]);}return '<div class="analytics-drill-backdrop" data-ui-action="analytics.closeDrill"></div><aside class="analytics-drill-panel" aria-label="Analyse-Detail"><header><div><small>Nachweis & Drill-down</small><h2>'+analyticsEsc(title)+'</h2></div><button type="button" aria-label="Detailansicht schließen" data-ui-action="analytics.closeDrill">×</button></header><div class="analytics-drill-body">'+body+'</div></aside>';}
function analyticsMainContent(view){if(analyticsUiState.level==='table')return analyticsTableExplorer(view);if(analyticsUiState.perspective==='finance')return analyticsUiState.level==='detail'?analyticsFinanceDetail(view):analyticsFinanceDashboard(view);if(analyticsUiState.perspective==='tax')return analyticsUiState.level==='detail'?analyticsTaxDetail(view):analyticsTaxDashboard(view);return analyticsUiState.level==='detail'?analyticsNkDetail(view):analyticsNkDashboard(view);}
function renderAnalyticsCenter(){const root=document.getElementById('analyticsCenterRoot');if(!root)return;analyticsEnsureRange();const view=analyticsView();root.innerHTML='<div class="analytics-center-top">'+analyticsPerspectiveTabs()+'</div>'+analyticsFilterToolbar(view)+analyticsLevelTabs()+analyticsQuestionBar()+'<div class="analytics-main-content">'+analyticsMainContent(view)+'</div>'+analyticsDrillPanel(view);const title=document.querySelector('#auswertungen .page-header__title');if(title)title.textContent='Analyse';const desc=document.querySelector('#auswertungen .page-header__description');if(desc)desc.textContent='Entwicklungen, Vergleiche und wirtschaftliche Auswertungen des Objekts.';}

/* Actions */
function analyticsSetPerspective(v){analyticsUiState.perspective=['nk','finance','tax'].includes(v)?v:'nk';analyticsUiState.detail=null;renderAnalyticsCenter();}
function analyticsSetLevel(v){analyticsUiState.level=['dashboard','detail','table'].includes(v)?v:'dashboard';analyticsUiState.detail=null;renderAnalyticsCenter();}
function analyticsSetFromPeriod(v){analyticsUiState.fromPeriodId=analyticsText(v);renderAnalyticsCenter();}
function analyticsSetToPeriod(v){analyticsUiState.toPeriodId=analyticsText(v);renderAnalyticsCenter();}
function analyticsSetComparison(v){analyticsUiState.comparison=analyticsText(v)||'previous';renderAnalyticsCenter();}
function analyticsSetReferencePeriod(v){analyticsUiState.referencePeriodId=analyticsText(v);renderAnalyticsCenter();}
function analyticsSetFilterKey(k,v){const f=analyticsFilter();f[k]=analyticsText(v)||'all';renderAnalyticsCenter();}
function analyticsSetCost(v){analyticsSetFilterKey('costId',v);}function analyticsSetTenant(v){analyticsSetFilterKey('tenantId',v);}function analyticsSetUnit(v){analyticsSetFilterKey('unitId',v);}function analyticsSetUsage(v){analyticsSetFilterKey('usage',v);}function analyticsSetCostArea(v){analyticsSetFilterKey('costArea',v);}function analyticsSetAllocationKey(v){analyticsSetFilterKey('allocationKey',v);}function analyticsSetStatus(v){analyticsSetFilterKey('status',v);}function analyticsSetDataQuality(v){analyticsSetFilterKey('dataQuality',v);}function analyticsSetDisplayMode(v){analyticsSetFilterKey('displayMode',v);}function analyticsToggleOpenChecks(v){analyticsFilter().onlyOpenChecks=!!v;renderAnalyticsCenter();}function analyticsToggleAnomalies(v){analyticsFilter().onlyAnomalies=!!v;renderAnalyticsCenter();}
function analyticsSetFinancePaymentStatus(v){analyticsSetFilterKey('paymentStatus',v);}function analyticsSetFinanceCostCategory(v){analyticsSetFilterKey('costCategory',v);}function analyticsSetFinanceObjectCostType(v){analyticsSetFilterKey('objectCostType',v);}function analyticsSetFinanceIncomeCategory(v){analyticsSetFilterKey('incomeCategory',v);}
function analyticsSetTaxCategory(v){analyticsSetFilterKey('taxCategory',v);}function analyticsSetTaxClassificationStatus(v){analyticsSetFilterKey('classificationStatus',v);}function analyticsSetTaxYear(v){analyticsSetFilterKey('taxYear',v);}
function analyticsResetFilter(k){const f=analyticsFilter();if(typeof f[k]==='boolean')f[k]=false;else if(k==='displayMode')f[k]='total';else f[k]='all';renderAnalyticsCenter();}
function analyticsSetDetailSection(v){analyticsUiState.detailSection[analyticsUiState.perspective]=analyticsText(v);analyticsUiState.level='detail';analyticsUiState.detail=null;renderAnalyticsCenter();}
function analyticsSetTableQuery(v){analyticsUiState.table.query=analyticsText(v);renderAnalyticsCenter();}function analyticsSetTableSort(v){analyticsUiState.table.sort=analyticsText(v)||'0';renderAnalyticsCenter();}function analyticsToggleTableDirection(){analyticsUiState.table.direction=analyticsUiState.table.direction==='asc'?'desc':'asc';renderAnalyticsCenter();}function analyticsSetTableGroup(v){analyticsUiState.table.group=['none','period','category'].includes(analyticsText(v))?analyticsText(v):'none';renderAnalyticsCenter();}function analyticsToggleTableColumn(index,checked){const p=analyticsUiState.perspective,i=Number(index);if(!Number.isInteger(i)||i<=0)return;const hidden=analyticsUiState.table.hiddenColumns[p]||[],show=checked===true||checked==='true';analyticsUiState.table.hiddenColumns[p]=show?hidden.filter(x=>x!==i):Array.from(new Set([...hidden,i]));renderAnalyticsCenter();}
function analyticsAskQuestion(k){k=analyticsText(k);if(k==='water'){analyticsUiState.perspective='nk';analyticsUiState.detailSection.nk='water';analyticsUiState.level='detail';}else if(k==='balances'){analyticsUiState.perspective='nk';analyticsUiState.detailSection.nk='balances';analyticsUiState.level='detail';}else if(k==='units-water'){analyticsUiState.perspective='nk';analyticsUiState.detailSection.nk='units';analyticsUiState.level='detail';}else if(k==='cost-change'){analyticsUiState.perspective='nk';analyticsUiState.detailSection.nk='costs';analyticsUiState.level='detail';}else if(k==='owner-costs'){analyticsUiState.perspective='finance';analyticsUiState.detailSection.finance='owner-costs';analyticsUiState.level='detail';}else if(k==='economics'){analyticsUiState.perspective='finance';analyticsUiState.detailSection.finance='economics';analyticsUiState.level='detail';}else if(k==='private-tax'){analyticsUiState.perspective='tax';analyticsUiState.detailSection.tax='private-tax';analyticsUiState.level='detail';}else if(k==='transition'){analyticsUiState.perspective='tax';analyticsUiState.detailSection.tax='transition';analyticsUiState.level='detail';}renderAnalyticsCenter();}
function analyticsQuickRange(mode){const p=analyticsAvailablePeriods();if(!p.length)return;if(mode==='current'){const x=p.find(q=>q.origin==='current')||p.at(-1);analyticsUiState.fromPeriodId=x.periodId;analyticsUiState.toPeriodId=x.periodId;}else if(mode==='last3'){analyticsUiState.fromPeriodId=p[Math.max(0,p.length-3)].periodId;analyticsUiState.toPeriodId=p.at(-1).periodId;}else{analyticsUiState.fromPeriodId=p[0].periodId;analyticsUiState.toPeriodId=p.at(-1).periodId;}renderAnalyticsCenter();}
function analyticsOpenDrill(payload){let d=payload;if(Array.isArray(d))d=d[0];if(typeof d==='string'){try{d=JSON.parse(d);}catch(_){d={type:'period',key:d,periodId:d};}}analyticsUiState.detail=d&&typeof d==='object'?d:null;renderAnalyticsCenter();}function analyticsCloseDrill(){analyticsUiState.detail=null;renderAnalyticsCenter();}

function analyticsExportMeta(view){const filters=analyticsActiveFilterItems().map(i=>i.label+': '+i.value).join(' | ')||'Keine';return [['Perspektive',analyticsPerspectiveLabel()],['Ansicht',analyticsUiState.level==='dashboard'?'Übersicht':analyticsUiState.level==='detail'?'Details':'Tabelle'],['Zeitraum',(view.models||[]).map(m=>m.period.label).join(' bis ')],['Vergleich',analyticsUiState.comparison],['Filter',filters],['Erstellt',new Date().toISOString()],['NK-Pro-Version',APP_VERSION],['Datenlage',(view.models||[]).map(m=>m.period.label+': '+m.period.quality.comparability).join(' | ')],['Vergleichbarkeit','Kennzahlenbezogen; fehlende oder fachlich nicht belastbare Werte erzeugen keine irreführenden Prozentwerte.']];}
function analyticsCsvEscape(v){const s=String(v??'');return /[;"\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}
function analyticsExportRows(view){const rows=[...analyticsExportMeta(view),[]];if(analyticsUiState.perspective==='finance'){rows.push(['Periode','Kaltmiete Soll','Kaltmiete Ist','Mietrealisierung %','NK-Vorauszahlungen','Laufende Objektkosten','Objektbetriebsergebnis','Cashflow','Cashflow-Status']);view.models.forEach(m=>rows.push([m.period.label,m.financial.rentTarget,m.financial.rentReceived,m.financial.rentRealization??'',m.financial.nkPrepayments,m.financial.operatingCosts,m.financial.operatingResult,m.financial.cashflowComplete?m.financial.cashflow:'',m.financial.cashflowComplete?'berechenbar':m.financial.cashflowReason]));}else if(analyticsUiState.perspective==='tax'){rows.push(['Periode','Kostenart','Gesamt','Vermietet','Privat','Leerstand','Sonstige','Steuerkategorie','Steuerjahr','Status','Umlageschlüssel','Quelle']);view.models.forEach(m=>m.tax.forEach(r=>rows.push([m.period.label,r.costName,r.total??'',r.rented??'',r.private??'',r.vacancy??'',r.other??'',r.taxCategory??'offen',r.taxYear??'offen',r.taxStatus,r.allocationKey,r.source])));}else{rows.push(['Periode','Kostenart','Gesamt','Vermietet','Privat','Leerstand','echte nicht umlagefähig','umlagefähig nicht umgelegt','Umlageschlüssel','Status']);view.models.forEach(m=>m.costs.filter(c=>c.active||c.total!==null).forEach(c=>rows.push([m.period.label,c.costName,c.total??'',c.rentedShare,c.privateShare,c.vacancyShare,c.trueNonAllocable,c.actualUnallocated,c.allocationKey,c.calculationStatus])));rows.push([]);rows.push(['Periode','Teilnehmer','Wohnung','Nutzungsart','Kostenanteil','Vorauszahlungen','Saldo']);view.models.forEach(m=>m.tenants.forEach(t=>rows.push([m.period.label,t.name,t.unitId,t.usageLabel,t.costShare,t.prepayments,t.balance])));}return rows;}
function analyticsExportCsv(){const view=analyticsView(),content=analyticsExportRows(view).map(r=>r.map(analyticsCsvEscape).join(';')).join('\n');NK_PRO_MODULES.exportService.download('NK-Pro_Analyse_'+analyticsUiState.perspective+'_'+APP_VERSION+'_'+new Date().toISOString().slice(0,10)+'.csv',content,'text/csv;charset=utf-8');}
function analyticsXmlCell(v){const num=typeof v==='number'&&Number.isFinite(v);return '<Cell><Data ss:Type="'+(num?'Number':'String')+'">'+analyticsEsc(v??'')+'</Data></Cell>';}function analyticsXmlSheet(name,rows){return '<Worksheet ss:Name="'+analyticsEsc(name.slice(0,31))+'"><Table>'+rows.map(r=>'<Row>'+r.map(analyticsXmlCell).join('')+'</Row>').join('')+'</Table></Worksheet>';}
function analyticsExportExcel(){const view=analyticsView(),meta=analyticsExportMeta(view),sheets=[analyticsXmlSheet('Übersicht',meta)];if(analyticsUiState.perspective==='tax'){sheets.push(analyticsXmlSheet('Einnahmen',[['Periode','Mieteinnahmen ohne Umlagen','Vereinnahmte Umlagen'],...view.models.map(m=>[m.period.label,m.metrics.taxRent.value,m.metrics.taxPrepayments.value])]));sheets.push(analyticsXmlSheet('Kosten',[['Periode','Kostenart','Gesamt','Vermietet','Privat','Leerstand','Sonstige'],...view.models.flatMap(m=>m.tax.map(r=>[m.period.label,r.costName,r.total??'',r.rented??'',r.private??'',r.vacancy??'',r.other??'']))]));sheets.push(analyticsXmlSheet('Privatanteil',[['Periode','Kostenart','Privatanteil','Umlageschlüssel'],...view.models.flatMap(m=>m.tax.filter(r=>analyticsFinite(r.private)&&Math.abs(r.private)>.005).map(r=>[m.period.label,r.costName,r.private,r.allocationKey]))]));sheets.push(analyticsXmlSheet('Leerstand',[['Periode','Kostenart','Leerstandsanteil'],...view.models.flatMap(m=>m.tax.filter(r=>analyticsFinite(r.vacancy)&&Math.abs(r.vacancy)>.005).map(r=>[m.period.label,r.costName,r.vacancy]))]));sheets.push(analyticsXmlSheet('Klassifikation',[['Periode','Kostenart','Steuerkategorie','Steuerjahr','Status'],...view.models.flatMap(m=>m.tax.map(r=>[m.period.label,r.costName,r.taxCategory??'offen',r.taxYear??'offen',r.taxStatus]))]));sheets.push(analyticsXmlSheet('Berechnungsnachweise',[['Periode','Kostenart','Regel','Umlageschlüssel','Quelle'],...view.models.flatMap(m=>m.tax.map(r=>[m.period.label,r.costName,r.usageRule,r.allocationKey,r.source]))]));sheets.push(analyticsXmlSheet('Datenquellen',[['Periode','periodId','Quelle','Vergleichbarkeit'],...view.models.map(m=>[m.period.label,m.period.periodId,m.period.source,m.period.quality.comparability])]));}else sheets.push(analyticsXmlSheet(analyticsUiState.perspective==='finance'?'Finanzen':'Analysewerte',analyticsExportRows(view).filter(r=>r.length)));const xml='<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'+sheets.join('')+'</Workbook>';NK_PRO_MODULES.exportService.download('NK-Pro_Analyse_'+analyticsUiState.perspective+'_'+APP_VERSION+'.xls',xml,'application/vnd.ms-excel;charset=utf-8');}
function analyticsPrint(){const view=analyticsView(),rows=analyticsExportRows(view).filter(r=>r.length),html='<!doctype html><html lang="de"><head><meta charset="utf-8"><title>'+analyticsEsc(analyticsPerspectiveLabel())+'</title><style>body{font-family:Segoe UI,Arial,sans-serif;color:#182230;padding:24px}table{border-collapse:collapse;width:100%;font-size:10px}td{border:1px solid #ccd3dc;padding:6px}@page{size:A4 landscape;margin:12mm}</style></head><body><h1>NK-Pro · '+analyticsEsc(analyticsPerspectiveLabel())+'</h1><p>'+analyticsEsc(analyticsPeriodRangeLabel())+' · '+analyticsEsc(APP_VERSION)+'</p><table>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+analyticsEsc(v)+'</td>').join('')+'</tr>').join('')+'</table><p>Vergleichbarkeit: kennzahlenbezogen. Fehlende Werte sind keine Nullwerte.</p></body></html>';const win=window.open('','_blank');if(!win)throw new Error('Druckfenster wurde vom Browser blockiert.');win.document.write(html);win.document.close();win.focus();setTimeout(()=>win.print(),120);}
